"""Brief original scene summaries; effects and callbacks remain causal."""
# id, date, recipients, title, body, choice A, effect A, callback A, choice B, effect B, callback B
SCENES = [
    (101, '1965.11.05', ['PKS', 'SVN'], '证件上的印章', '归仁推行良民证，军警与地方官分账。收入可以养部队，也能转入私人关系网。', '照旧分账，先让地方机构运转。', 'add_political_power = 80 add_to_variable = { v65_patronage = 10 } subtract_from_variable = { v65_public_trust = 8 }', '账面收入超过了预期，地方警察也很快交来了新的名册。', '公开收费标准，接受乡村代表申诉。', 'add_political_power = -35 add_to_variable = { v65_public_trust = 8 } subtract_from_variable = { v65_patronage = 3 }', '村长带来了几条过去不肯说的路。'),
    (102, '1966.05.01', ['PKS', 'SVN'], '镜头之外的人', '参谋准备上报战果，军医另有一份伤亡册。战报影响追加军援和实际补充名额。', '让报纸刊登那份胜利。', 'add_political_power = 60 add_to_variable = { v65_patronage = 6 } set_country_flag = v65_inflated_reports', '晋升与追加军需一同到来。', '把伤亡附在战报后面。', 'add_political_power = -25 add_to_variable = { v65_public_trust = 5 } v65_upgrade_staff = yes', '报纸没有采用那张照片，上级的回信也很冷淡。'),
    (103, '1967.03.01', ['PKS', 'SVN'], '日海的第一份长约', '日海争取运输长约。合同能提供稳定收入，也会把采购和军官关系绑在一起。', '接受独家合同，建立自己的军需网络。', 'v65_upgrade_contracts = yes add_to_variable = { v65_patronage = 8 } SVN = { add_to_variable = { v65_park_trust = 5 } }', '卡车准时抵达，临时拨款不再是每天的争吵。', '拆分采购，保留核查与退出条款。', 'v65_upgrade_logistics = yes add_political_power = -35 subtract_from_variable = { v65_patronage = 4 }', '采购速度慢了一些，几家商号退出了报价。'),
    (201, '1968.07.01', ['PKS', 'SVN'], '撤军表上的空格', '美韩撤军留下库存与运输合同。朴可以经营这些渠道，或争取继续保留援助。', '用军需合同接管库存。', 'add_equipment_to_stockpile = { type = motorized_equipment_1 amount = 300 producer = ROOT } add_to_variable = { v65_patronage = 8 }', '车队扩大了，维修账也扩大了。', '把设备与维修队一同交给地方军区。', 'v65_upgrade_training = yes add_to_variable = { v65_public_trust = 5 } SVN = { add_to_variable = { v65_island_trust = 5 } }', '地方军区送来了一份简短的收据。'),
    (202, '1970.04.01', ['SVN', 'PKS'], '岛上的第二套公章', '富国岛有自己的驻军、港口和生意。西贡要求统一调度，岛方要求保留任命与收入。', '允许特别区自主管理港口与安置。', 'add_political_power = 35 SVN = { add_to_variable = { v65_island_trust = 10 } } add_to_variable = { v65_patronage = 4 }', '船期稳定下来，家属也有了住处。', '保持中央任命，拨款改善港口。', 'add_political_power = -60 31 = { if = { limit = { is_owned_by = ROOT } add_building_construction = { type = infrastructure level = 1 instant_build = yes } } } add_to_variable = { v65_public_trust = 5 }', '新拨款终于让码头工程开工。'),
    (203, '1971.06.01', ['SVN', 'PKS'], '第五支机动部队', '中央需要机动部队，岛上需要留下守军。兵从哪里出、补给由谁发，决定部队以后听谁的。', '由协调会直接掌握任命。', 'v65_upgrade_staff = yes add_to_variable = { v65_patronage = 5 } SVN = { add_to_variable = { v65_park_trust = 7 } }', '命令变快了。', '分散骨干，训练各区自己的预备队。', 'v65_upgrade_training = yes add_to_variable = { v65_public_trust = 4 } SVN = { add_to_variable = { v65_island_trust = 4 } }', '几支地方预备队陆续完成整训。'),
    (301, '1972.03.30', ['SVN', 'PKS', 'DNM'], '广治以南的路', '广治前线承压。投入精锐可能守住公路，也可能丢掉最后的机动预备队。', '让精锐进入预备阵地。', 'v65_upgrade_training = yes add_war_support = 0.04 add_to_variable = { v65_war_fatigue = 5 }', '增援提高了守军的信心，后方巡逻却变得稀疏。', '扩大纵深，准备有秩序地收缩。', 'add_ideas = v65_prepared_defence add_stability = -0.03 v65_upgrade_logistics = yes', '仓库开始向后转移。'),
    (302, '1972.08.01', ['SVN'], '每个司令自己的战争', '各军区自留部队，中央的调令开始失效。总统府可以收回指挥权，也可以承认地方自治。', '建立跨区参谋机构，维持中央指挥。', 'v65_upgrade_staff = yes add_political_power = -40 add_to_variable = { v65_public_trust = 4 }', '联络人员增加了，争执并没有减少。', '承认军区自治，各自处理内部叛乱。', 'v65_devolve_regions = yes subtract_from_variable = { v65_patronage = 3 }', '新的军区旗帜出现在作战图上。'),
    (303, '1973.02.01', ['PKS', 'SVN'], '公报与病床', '战果公报已经发出，损耗仍待补齐。继续报捷有利于援助，核实编制则有利于下次调兵。', '先发布胜利，争取更多援助。', 'add_political_power = 75 add_war_support = 0.03 set_country_flag = v65_inflated_reports add_to_variable = { v65_patronage = 5 }', '援助承诺比实际物资来得更快。', '按真实缺额组织轮换。', 'subtract_from_variable = { v65_war_fatigue = 6 } v65_upgrade_training = yes add_political_power = -35', '漂亮的总结被压在抽屉里。'),
    (401, '1974.12.01', ['SVN', 'PKS'], '西原撤退预案', '西原交通线受到威胁。守城、撤向海岸和分区固守，需要不同的部队与补给安排。', '优先保全部队与军需。', 'add_equipment_to_stockpile = { type = infantry_equipment_2 amount = 1000 producer = ROOT } add_to_variable = { v65_patronage = 6 } subtract_from_variable = { v65_public_trust = 6 }', '军需储备增加了，乡村却开始自行寻找出路。', '公开安置顺序，给平民留出运力。', 'v65_upgrade_logistics = yes add_political_power = -50 add_to_variable = { v65_public_trust = 7 }', '车队的速度没有变快，争抢却少了一些。'),
    (402, '1975.03.15', ['SVN', 'PKS'], '总统府的两封回电', '总统府与前线的命令发生冲突。继任与撤退安排将决定军官继续服从中央，还是各自保全部队。', '保留总统名义，由军政协调会决定调动。', 'SVN = { add_to_variable = { v65_park_trust = 10 } subtract_from_variable = { v65_thieu_trust = 5 } } add_to_variable = { v65_patronage = 7 } v65_upgrade_staff = yes', '调动顺序终于统一了。', '要求各军区公开自己的保存兵力计划。', 'add_to_variable = { v65_public_trust = 6 } SVN = { subtract_from_variable = { v65_park_trust = 4 } add_to_variable = { v65_thieu_trust = 8 } } add_political_power = -45', '有的军区如实交表，有的只交来一个大概数字。'),
    (403, '1975.08.01', ['PKS', 'SVN', 'PHQ'], '留给岛上的保证', '大陆局势恶化，富国岛需要决定接收谁、留下多少驻军，以及是否继续承担大陆作战。', '继续援助大陆，但限制新的承诺。', 'v65_upgrade_logistics = yes SVN = { add_to_variable = { v65_island_trust = 8 } } subtract_from_variable = { v65_war_fatigue = 3 }', '船上的货单被重新核定。', '把岛作为下一次反攻的基地。', 'add_war_support = 0.06 add_to_variable = { v65_war_fatigue = 5 } SVN = { subtract_from_variable = { v65_island_trust = 8 } }', '军营里重新挂起了训练计划。'),
    (501, '1976.04.01', ['SVN', 'PKS', 'MKG', 'HLC', 'PHQ'], '谁在替谁维持秩序', '地方部队各自筹款、清剿和招人。中央要恢复调度，必须先解决军饷和任命。', '以援助换取联合作战承诺。', 'add_political_power = -60 v65_upgrade_staff = yes add_to_variable = { v65_patronage = 4 }', '部队终于调动了，军区也得到了新的军需清单。', '承认本地优先，安排共同联络。', 'add_to_variable = { v65_public_trust = 6 } subtract_from_variable = { v65_local_unrest = 2 } v65_upgrade_signals = yes', '军区留下了主力，派来几名熟悉乡村的联络官。'),
    (502, '1977.05.01', ['KHM', 'RKH'], '国境线上的旧仓库', '柬埔寨内战与越南战线共用部分运输网络。仓库和通道可以换取军援，也会招来干预。', '继续以通道换取军需和外交筹码。', 'add_equipment_to_stockpile = { type = infantry_equipment_2 amount = 800 producer = NVN } add_to_variable = { v65_patronage = 7 } NVN = { add_to_variable = { v65_trail_level = 1 } }', '军需抵达了，联络人员也更频繁地出入。', '缩减秘密运输，先处理本国村庄。', 'add_to_variable = { v65_public_trust = 7 } subtract_from_variable = { v65_war_fatigue = 4 } NVN = { subtract_from_variable = { v65_trail_level = 1 } clamp_variable = { var = v65_trail_level min = 0 max = 5 } }', '几辆车空着返回边境。'),
    (503, '1978.07.01', ['SVN', 'PHQ', 'MKG', 'PKS'], '孩子记得的是哪一年', '长期驻军带来安置、学校与军属开支。现有预算不足以同时维持全部动员和地方建设。', '继续优先保障军队与动员。', 'add_war_support = 0.05 add_to_variable = { v65_war_fatigue = 4 } add_to_variable = { v65_patronage = 4 }', '动员计划照常执行。', '把安置、学校与轮休写进正式预算。', 'add_political_power = -60 add_to_variable = { v65_public_trust = 8 } subtract_from_variable = { v65_war_fatigue = 7 }', '预算争论持续了很久。'),
    (601, '1966.09.01', ['NVN', 'FNL'], '粮袋与姓名', '北方征粮与补充兵员依赖村庄组织。扩大征集能增加兵力，也会影响下一轮运输。', '按前线需要扩大征集。', 'add_equipment_to_stockpile = { type = infantry_equipment_2 amount = 700 producer = ROOT } subtract_from_variable = { v65_public_trust = 5 } add_to_variable = { v65_war_fatigue = 3 }', '物资抵达了。', '给村庄留出粮食与轮换名额。', 'v65_upgrade_logistics = yes add_to_variable = { v65_public_trust = 6 } add_political_power = -35', '第一批货物少了一些。'),
    (602, '1969.10.01', ['FNL', 'NVN'], '白天的合作对象', '南方基层组织同时接触地方官、村长和游击队。合作对象需要核实，不能只看白天的登记册。', '接受有条件的地方合作。', 'v65_upgrade_signals = yes add_to_variable = { v65_public_trust = 4 } add_to_variable = { v65_patronage = 4 }', '仓库用上了，新的保护关系也随之建立。', '拒绝私人交换，维持组织纪律。', 'add_political_power = 45 subtract_from_variable = { v65_patronage = 4 } add_to_variable = { v65_local_unrest = 1 }', '队伍改走更远的山路。'),
    (603, '1973.09.01', ['NVN', 'FNL'], '停火之后的另一份命令', '停火没有解除地方武装。继续扩张还是保存组织，将改变下一阶段的准备。', '保持动员，为下一轮进攻储备。', 'v65_upgrade_training = yes add_to_variable = { v65_war_fatigue = 5 } add_war_support = 0.04', '储备增加了，轮休仍然推迟。', '恢复基层生产与有限轮休。', 'random_owned_controlled_state = { add_building_construction = { type = industrial_complex level = 1 instant_build = yes } } subtract_from_variable = { v65_war_fatigue = 5 } add_to_variable = { v65_public_trust = 5 }', '一部分人回到了田间和修械所。'),
    (604, '1976.11.01', ['NVN', 'FNL'], '夺取之后，怎样留下', '控制县城后仍需接管村庄、粮运与干部任命。部队必须决定优先投入哪个环节。', '先以军令统一地方。', 'add_political_power = 60 add_to_variable = { v65_local_unrest = 2 } subtract_from_variable = { v65_public_trust = 5 }', '命令很快传到各处。', '保留可用的行政与民生网络。', 'add_political_power = -50 add_to_variable = { v65_public_trust = 8 } v65_upgrade_staff = yes', '整编比计划中慢。'),
    (605, '1967.06.01', ['KHM'], '王宫与参谋部', '王宫与军方争夺预算和任命。对外中立需要国内力量支持。', '给参谋部更大的征调权。', 'v65_upgrade_training = yes add_to_variable = { v65_patronage = 6 } subtract_from_variable = { v65_public_trust = 4 }', '部队补充得更快，地方征粮也更加频繁。', '坚持地方预算与军费核查。', 'v65_upgrade_staff = yes add_political_power = -40 add_to_variable = { v65_public_trust = 6 }', '一些军费申请被退回重填。'),
    (606, '1970.10.01', ['KHM'], '谁来代表柬埔寨', '金边的权力安排面临改组。维持王国或由朗诺建立共和国，将改变政府领导人与对外路线。', '建立高棉共和国，由军方承担责任。', 'set_cosmetic_tag = V65_KHMER_REPUBLIC if = { limit = { has_character = v65_lon_nol NOT = { has_country_flag = v65_republic_leader } } set_country_flag = v65_republic_leader add_country_leader_role = { character = v65_lon_nol country_leader = { ideology = despotism expire = "1990.1.1" } promote_leader = yes } } add_to_variable = { v65_patronage = 8 } v65_upgrade_training = yes', '公文换了抬头，军方获得更多任命权。', '保留王国名义，重新谈判军政权限。', 'add_to_variable = { v65_public_trust = 6 } v65_upgrade_staff = yes add_political_power = -40', '王室名义被保留下来，各方签署了一份新的权限清单。'),
    (607, '1968.02.01', ['RKH'], '根据地里的登记册', '根据地需要粮食、人员和运输渠道。扩充动员与争取村庄合作需要不同安排。', '以军事纪律执行统一征集。', 'add_equipment_to_stockpile = { type = infantry_equipment_2 amount = 600 producer = ROOT } subtract_from_variable = { v65_public_trust = 8 } add_to_variable = { v65_patronage = 6 }', '登记册按时上交。', '允许基层说明差异，维持村庄生产。', 'add_to_variable = { v65_public_trust = 8 } add_political_power = -35 v65_upgrade_logistics = yes', '登记慢了下来，一些问题终于不再被改成好看的数字。'),
    (608, '1974.06.01', ['RKH'], '越境来的联络人', '越境联络带来物资，也带来对运输路线和指挥权的要求。根据地需要决定接受多少外部安排。', '扩大共同通道与军需合作。', 'NVN = { add_to_variable = { v65_trail_level = 1 } } add_equipment_to_stockpile = { type = infantry_equipment_2 amount = 900 producer = NVN } add_to_variable = { v65_patronage = 8 }', '仓库里多了武器，会议上也多了需要考虑的外部意见。', '限制外部条件，优先根据地自身补给。', 'v65_upgrade_logistics = yes add_to_variable = { v65_public_trust = 5 } add_political_power = -50', '部分援助没有抵达。'),
]
